for name, fixes in [("ru.json", ru_fixes), ("uk.json", uk_fixes)]:
    path = base / name
    data = json.loads(path.read_text(encoding="utf-8"))
    for p, v in fixes.items():
        set_path(data, p, v)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"{name}: applied {len(fixes)} fixes")

bad_ru = ["сфокусир", "подвале", "вылеплен", "иммерсив", "рукописн", "gallery-реверб", "перформанс", "Валидация", "воркфлоу", "центрирован"]
bad_uk = ["сфокусов", "підвалі", "виліплен", "занурювальн", "рукописн", "gallery-реверб", "перформанс", "Валідація", "воркфлоу", "ліплення"]
for name, bad in [("ru.json", bad_ru), ("uk.json", bad_uk)]:
    text = (base / name).read_text(encoding="utf-8")
    hits = [b for b in bad if b in text]
    print(f"{name} leftover: {hits or 'none'}")
